const FRAME_CONN_TURN_UI_NO_ROLL_ACTION_IDS =
  Object.freeze(
    new Set([
      "movement.standard",
      "movement.jump",
      "movement.climb",
      "movement.fly",
      "movement.teleport",

      "quick.boost",
      "quick.hide",
      "quick.prepare",
      "quick.shut-down",
      "quick.self-destruct",

      "full.disengage",
      "full.mount-dismount",

      "special.end-turn"
    ])
  );


/**
 * Executable workflows which do not represent an attack/check roll.
 *
 * These actions still receive an Execute control, but presentation
 * must not imply that pressing it rolls a d20.
 */
const FRAME_CONN_TURN_UI_EXECUTE_ONLY_ACTION_IDS =
  Object.freeze(
    new Set([
      "full.boot-up"
    ])
  );

  return (
    !FRAME_CONN_TURN_UI_NO_ROLL_ACTION_IDS
      .has(
        action.id
      ) &&
    !FRAME_CONN_TURN_UI_EXECUTE_ONLY_ACTION_IDS
      .has(
        action.id
      )
  );
}


function frameConnTurnUiCommittedActionCanExecute(
  action
) {
  if (
    !action?.id
  ) {
    return false;
  }


  return (
    !FRAME_CONN_TURN_UI_NO_ROLL_ACTION_IDS
      .has(
        action.id
      )
  );
}

